import glob
import sys

# find existing perl poi files to create blocklist
files = glob.glob("lib/visualLab/data/peruPoi.ts") + glob.glob("lib/visualLab/data/poiExtraPeru*.ts")
blocklist = set()
for f in files:
    with open(f, "r", encoding="utf-8") as file:
        lines = file.readlines()
        for i, line in enumerate(lines):
            if "name:" in line and "de:" in line:
                try:
                    # extract 'de: "Name"'
                    import re
                    match = re.search(r'de:\s*"([^"]+)"', line)
                    if not match:
                        match = re.search(r'de:\s*"([^"]+)"', lines[i+1])
                    if match:
                        blocklist.add(match.group(1).lower())
                except:
                    pass
            elif "de:" in line and "name" not in line:
                # might be name de inside a block
                try:
                    import re
                    match = re.search(r'de:\s*"([^"]+)"', line)
                    if match:
                        # only add if very short to avoid adding descriptions
                        val = match.group(1).strip()
                        if len(val) < 30:
                            blocklist.add(val.lower())
                except:
                    pass

print("Blocklist items:", len(blocklist))

valid_pois = []
for c in cities:
    (uid, ptype, parent, lon, lat, 
    n_de, d_de, d_hu, d_ro, d_en, 
    f1_de, f1_hu, f1_ro, f1_en, 
    f2_de, f2_hu, f2_ro, f2_en) = c
    
    if n_de.lower() in blocklist:
        continue
        
    # ensure no duplicates in the current list
    if any(p["id"] == f"{uid}-cities-v2" for p in valid_pois):
        continue
    if any(p["name_de"].lower() == n_de.lower() for p in valid_pois):
        continue
    
    valid_pois.append({
        "id": f"{uid}-cities-v2",
        "type": ptype,
        "parent": parent,
        "lon": lon,
        "lat": lat,
        "name_de": n_de, "name_hu": n_de, "name_ro": n_de, "name_en": n_de,
        "desc_de": d_de, "desc_hu": d_hu, "desc_ro": d_ro, "desc_en": d_en,
        "f1_de": f1_de, "f1_hu": f1_hu, "f1_ro": f1_ro, "f1_en": f1_en,
        "f2_de": f2_de, "f2_hu": f2_hu, "f2_ro": f2_ro, "f2_en": f2_en,
    })

if len(valid_pois) < 70:
    print(f"Warning: Only {len(valid_pois)} POIs generated.")
    # we need more to reach exactly 70
    # we have 70 in list, wait, let's see how many get accepted.
else:
    valid_pois = valid_pois[:70]


