with open("lib/visualLab/data/poiExtraPeruCitiesV2.ts", "w", encoding="utf-8") as out:
    out.write('import type { POI } from "./poi";\n\n')
    out.write('export const poiExtraPeruCitiesV2: POI[] = [\n')
    
    for i, p in enumerate(valid_pois):
        out.write('  {\n')
        out.write(f'    id: "{p["id"]}",\n')
        out.write(f'    type: "{p["type"]}",\n')
        out.write(f'    parent: "{p["parent"]}",\n')
        out.write(f'    coords: [{p["lon"]}, {p["lat"]}],\n')
        out.write('    name: {\n')
        out.write(f'      de: "{p["name_de"]}",\n')
        out.write(f'      hu: "{p["name_hu"]}",\n')
        out.write(f'      ro: "{p["name_ro"]}",\n')
        out.write(f'      en: "{p["name_en"]}"\n')
        out.write('    },\n')
        out.write('    description: {\n')
        out.write(f'      de: "{p["desc_de"]}",\n')
        out.write(f'      hu: "{p["desc_hu"]}",\n')
        out.write(f'      ro: "{p["desc_ro"]}",\n')
        out.write(f'      en: "{p["desc_en"]}"\n')
        out.write('    },\n')
        out.write('    facts: {\n')
        out.write(f'      de: ["{p["f1_de"]}", "{p["f2_de"]}"],\n')
        out.write(f'      hu: ["{p["f1_hu"]}", "{p["f2_hu"]}"],\n')
        out.write(f'      ro: ["{p["f1_ro"]}", "{p["f2_ro"]}"],\n')
        out.write(f'      en: ["{p["f1_en"]}", "{p["f2_en"]}"]\n')
        out.write('    }\n')
        if i == len(valid_pois) - 1:
            out.write('  }\n')
        else:
            out.write('  },\n')
            
    out.write('];\n')

print(f"Generated {len(valid_pois)} POIs.")
